arguments.new_str:
using System.Diagnostics;
using TextAnalysis;

// Build the analyzer with ~300 words of sample text
var text = string.Join(" ", Enumerable.Range(0, 20).Select(_ =>
    "The quick brown fox jumps over the lazy dog and the cat sat on the mat"));
var analyzer = new TextAnalyzer(text);

const int WarmupIterations = 100;
const int Iterations = 100_000;

Console.WriteLine($"Runtime: {System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription}");
Console.WriteLine($"Words: {analyzer.WordCount}");
Console.WriteLine($"Warmup: {WarmupIterations}, Measured iterations: {Iterations}");
Console.WriteLine();

// Warmup + benchmark helper
void Bench(string name, Action action)
{
    for (int i = 0; i < WarmupIterations; i++) action();
    GC.Collect();
    GC.WaitForPendingFinalizers();
    GC.Collect();

    long memBefore = GC.GetTotalAllocatedBytes(precise: true);
    var sw = Stopwatch.StartNew();
    for (int i = 0; i < Iterations; i++) action();
    sw.Stop();
    long memAfter = GC.GetTotalAllocatedBytes(precise: true);

    double nsPerOp = sw.Elapsed.TotalNanoseconds / Iterations;
    double bytesPerOp = (double)(memAfter - memBefore) / Iterations;
    Console.WriteLine($"  {name,-25} {nsPerOp,10:F1} ns/op    {bytesPerOp,8:F0} B/op");
}

Console.WriteLine("Results:");
Bench("AverageWordLength", () => analyzer.AverageWordLength());
Bench("WordLengthHistogram", () => analyzer.WordLengthHistogram());
Bench("UniqueWordCount", () => analyzer.UniqueWordCount());

